  subnet_id         = "subnet-0562ef1d304b968f4"
  allocation_id     = "eipalloc-0047fa56c40637c3b"
  connectivity_type = "public"
  tags = {
    pike = "permissions"
  }
}

provider "aws" {
  region = "us-west-1"
}

resource "aws_default_network_acl" "pike" {
